70	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
71	
72	    /**
73	     * Dedicated logger for the welcome-notification queue. On a successful create a single line
74	     * carrying the new owner's id and member id is emitted here, standing in for enqueuing a
75	     * welcome notification to the owner.
76	     */
