78	
79	    /**
80	     * Assigns the monotonically increasing sequence number carried by each structured
81	     * {@link OwnerCreatedEvent}. Static so the order spans every create handled by this endpoint,
82	     * regardless of the controller instance, giving the audit event stream a total order.
83	     */
84	    private static final AtomicLong AUDIT_EVENT_SEQUENCE = new AtomicLong();
