140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
143	        HttpHeaders headers = new HttpHeaders();
144	        String idempotencyKey = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
145	        Integer existingId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey);
146	        if (existingId != null) {
147	            Owner existing = this.clinicService.findOwnerById(existingId);
148	            if (existing != null) {
149	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
150	            }
151	        }
152	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
153	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
154	        owner.setTelephone(normalizedTelephone);
155	        owner.setEmail(normalizeEmail(owner.getEmail()));
156	        applyAddress(owner);
157	        validatePostcode(owner.getCity(), owner.getPostcode());
158	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
159	        if (effectiveRegistrationDate == null) {
160	            effectiveRegistrationDate = LocalDate.now();
161	        } else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
162	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
163	                "registrationDate must not be later than the current server date");
164	        }
165	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
166	        owner.setRegistrationDate(effectiveRegistrationDate);
167	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
168	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
169	                "the maximum number of owners that may be created today has been reached");
170	        }
171	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
172	        // The household id is deterministic (derived from the last name and postcode), so every
173	        // owner is keyed to its household automatically, regardless of creation order.
174	        this.clinicService.assignHousehold(owner);
175	        // An owner joining an existing household is now admitted rather than rejected; their
176	        // membership level is instead capped relative to the household (see the level-ceiling rule
177	        // applied via the membershipLevelCap below).
178	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner.getHouseholdId(), null);
179	        if (isIdentityKeyInUse(ownerMapper.toIdentityKey(owner), null)) {
180	            throw new ResponseStatusException(HttpStatus.CONFLICT,
181	                "an owner with the same identity already exists");
182	        }
183	        int ownersInCity = countOwnersInCity(owner.getCity());
184	        if (ownersInCity >= CITY_CAPACITY) {
185	            throw new ResponseStatusException(HttpStatus.CONFLICT,
186	                "city has reached its maximum number of owners");
187	        }
188	        owner.setCapacityWarning(ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD);
189	        owner.setMemberId(memberIdFor(owner));
190	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
191	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
192	        owner.setMembershipLevelCap(householdMembershipLevelCap(owner.getHouseholdId()));
193	        owner.setBulkSignupWarning(
194	            countOwnersRegisteredOn(effectiveRegistrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
195	        // A declared household member (one created with 'sharesHousehold' that joins an existing
196	        // household) is not a suspected duplicate, so it is never flagged as a possible duplicate.
197	        boolean declaredHouseholdMember = sharesHousehold && householdInUse;
198	        Owner softDuplicate = declaredHouseholdMember ? null : findPossibleDuplicate(owner);
199	        owner.setPossibleDuplicate(softDuplicate != null);
200	        owner.setPossibleDuplicateOf(softDuplicate == null ? null : softDuplicate.getId());
201	        this.clinicService.saveOwner(owner);
202	        this.idempotencyKeyRegistry.record(idempotencyKey, owner.getId());
203	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
204	        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
205	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
206	            ownerDto.getMembershipLevel());
207	        OwnerCreatedEvent event = OwnerCreatedEvent.of(AUDIT_EVENT_SEQUENCE.incrementAndGet(),
208	            owner.getId(), primaryIdentifier(owner), ownerDto.getOwnerSegment(),
209	            ownerDto.getMembershipLevel());
210	        AUDIT.info(event.toJson());
211	        NOTIFY.info("welcome queued: ownerId={} memberId={}", owner.getId(), owner.getMemberId());
212	        headers.setLocation(UriComponentsBuilder.newInstance()
213	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
214	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
215	    }
