314	    /**
315	     * The owner's current primary identifier, carried by the structured {@link OwnerCreatedEvent}.
316	     * An owner's primary identifier is its {@code memberId}; this single accessor is the one place that
317	     * decides which field is primary, so the audit event always carries the member id.
318	     *
319	     * @param owner the created owner
320	     * @return the owner's current primary identifier
321	     */
322	    private String primaryIdentifier(Owner owner) {
323	        return owner.getMemberId();
324	    }
325	
326	    /**
327	     * Builds the member id for a new owner, formatted {@code '<REGION><FY><HASH8><CHK>'} where REGION is
328	     * the version-2 region code — the region derived from the owner's postcode (preferring the postcode,
329	     * falling back to the city table, else {@code 'UNKNOWN'}; see {@link OwnerMapper#regionOf(Owner)})
330	     * with the fixed {@link IdentityKeyUtils#IDENTITY_VERSION_TAG 'V2' version tag} appended, FY is the
331	     * two-digit fiscal
332	     * year (starting 1 July; see {@link OwnerMapper#fiscalYear(LocalDate)}) of the business-day-adjusted
333	     * registration date, HASH8 is the first 8 upper-case hex characters of the SHA-256 digest of the
334	     * owner's normalized E.164 telephone concatenated with the last name, and CHK is a single Luhn check
335	     * digit computed over the digits of {@code '<REGION><FY><HASH8>'} (see
336	     * {@link IdentityKeyUtils#luhnCheckDigit(String)}), e.g. {@code 'NSWV2271A2B3C4D5'}. The id carries no
337	     * sequence number, so its base form is a stable function of the owner's region, fiscal year and
338	     * telephone/last-name identity rather than of creation order.
339	     *
340	     * <p>When that computed id already belongs to an existing owner it is de-duplicated by appending
341	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that yields an id no existing owner
342	     * already has; the de-duplicated id is returned.
343	     *
344	     * @param owner the owner being created, with its telephone already normalized to E.164 form and its
345	     *              registration date already business-day-adjusted
346	     * @return the assigned, collision-free member id
347	     */
348	    private String memberIdFor(Owner owner) {
349	        // Version-2 region code: the plain region with the fixed 'V2' version tag mixed in, so the member
350	        // id (and every value derived from it) changes and no version-1 member id is produced again. The
351	        // user-facing locality keeps the plain, untagged region (see OwnerMapper.toLocality).
352	        String region = ownerMapper.regionOf(owner) + IdentityKeyUtils.IDENTITY_VERSION_TAG;
353	        String fy = String.format("%02d", OwnerMapper.fiscalYear(owner.getRegistrationDate()) % 100);
354	        String hash8 = IdentityKeyUtils.sha256UpperHex(owner.getTelephone() + owner.getLastName())
355	            .substring(0, 8);
356	        String base = region + fy + hash8;
357	        String memberId = base + IdentityKeyUtils.luhnCheckDigit(base);
358	        if (!isMemberIdInUse(memberId)) {
359	            return memberId;
360	        }
361	        int n = 2;
362	        String candidate = memberId + "-" + n;
363	        while (isMemberIdInUse(candidate)) {
364	            n++;
365	            candidate = memberId + "-" + n;
366	        }
367	        return candidate;
368	    }
369	
370	    /**
371	     * Determines whether any existing owner already carries the given {@code memberId}, compared
372	     * exactly. Called while assigning a new owner's member id so collisions can be de-duplicated.
373	     *
374	     * @param memberId the candidate member id to look for
375	     * @return {@code true} if an existing owner already has that member id
376	     */
377	    private boolean isMemberIdInUse(String memberId) {
378	        for (Owner existing : this.clinicService.findAllOwners()) {
379	            if (memberId.equals(existing.getMemberId())) {
380	                return true;
381	            }
382	        }
383	        return false;
384	    }
385	
386	    /**
387	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
388	     * owner's city already contains this many owners.
389	     */
390	    private static final int CITY_CAPACITY = 50;
391	
392	    /**
393	     * The number of owners a city must already contain before a new owner in it is flagged with
394	     * {@code capacityWarning}. Once the city holds this many owners (but fewer than
395	     * {@link #CITY_CAPACITY}), the create still succeeds but is flagged as approaching the capacity
396	     * limit.
397	     */
398	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
399	
400	    /**
401	     * The maximum number of owners that may be created on a single day. A create is rejected with
402	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
403	     * {@code registrationDate}.
404	     */
405	    private static final int DAILY_CREATE_LIMIT = 100;
406	
407	    /**
408	     * The number of owners that must already have been created for the current day before a new
409	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
410	     * owners already carry today's {@code registrationDate}.
411	     */
412	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
413	
414	    /**
415	     * The fixed public holidays that the business-day roll skips. A registration date landing on one
416	     * of these dates is rolled forward, exactly as it is for a weekend day.
417	     */
418	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
419	        LocalDate.parse("2026-01-01"),
420	        LocalDate.parse("2026-01-26"),
421	        LocalDate.parse("2026-04-25"),
422	        LocalDate.parse("2026-12-25"),
423	        LocalDate.parse("2026-12-28"));
424	
425	    /**
426	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday, a
427	     * Sunday or a listed public holiday is advanced one day at a time until it lands on a weekday
428	     * that is not a public holiday, while a date already on a non-holiday weekday is returned
429	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
430	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
431	     * falls on a business day.
432	     *
433	     * @param date the effective registration date
434	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
435	     */
436	    private static LocalDate rollToBusinessDay(LocalDate date) {
437	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
438	            date = date.plusDays(1);
439	        }
440	        return date;
441	    }
442	
443	    private static boolean isWeekend(LocalDate date) {
444	        return switch (date.getDayOfWeek()) {
445	            case SATURDAY, SUNDAY -> true;
446	            default -> false;
447	        };
448	    }
449	
450	    /**
451	     * Counts the existing owners whose {@code registrationDate} equals the given (already
452	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
453	     * business day. Called before a new owner is saved, so the returned value reflects the number of
454	     * owners created for that day prior to this create.
455	     *
456	     * @param date the adjusted business-day registration date to count against
457	     * @return the number of existing owners registered on that date
458	     */
459	    private int countOwnersRegisteredOn(LocalDate date) {
460	        return (int) this.clinicService.findAllOwners().stream()
461	            .filter(existing -> date.equals(existing.getRegistrationDate()))
462	            .count();
463	    }
464	
465	    /**
466	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
467	     *
468	     * @param city the city to count owners for
469	     * @return the number of existing owners in that city
470	     */
471	    private int countOwnersInCity(String city) {
472	        return (int) this.clinicService.findAllOwners().stream()
473	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
474	            .count();
475	    }
476	
477	    /**
478	     * Counts the existing owners that already share the given first name and last name, comparing
479	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
480	     * the number of namesakes that existed prior to this create.
481	     *
482	     * @param firstName the new owner's first name
483	     * @param lastName  the new owner's last name
484	     * @return the number of existing owners with the same first and last name
485	     */
486	    private int countNamesakes(String firstName, String lastName) {
487	        int count = 0;
488	        for (Owner existing : this.clinicService.findAllOwners()) {
489	            if (firstName.equalsIgnoreCase(existing.getFirstName())
490	                && lastName.equalsIgnoreCase(existing.getLastName())) {
491	                count++;
492	            }
493	        }
494	        return count;
495	    }
496	
497	    /**
498	     * Counts the existing owners that already belong to the given household (i.e. that share the
499	     * given {@code householdId}). Called before a new owner is saved, so adding one for the owner
500	     * being created yields the household's total size at the moment of creation. Owners without a
501	     * household id are ignored.
502	     *
503	     * @param householdId the new owner's assigned household id
504	     * @return the number of existing owners already in that household
505	     */
506	    private int countHouseholdMembers(String householdId) {
507	        if (householdId == null) {
508	            return 0;
509	        }
510	        int count = 0;
511	        for (Owner existing : this.clinicService.findAllOwners()) {
512	            if (householdId.equals(existing.getHouseholdId())) {
513	                count++;
514	            }
515	        }
516	        return count;
517	    }
518	
519	    /**
520	     * Computes the membership-level ceiling for a new owner joining the given household: one above the
521	     * current maximum effective membership level among the existing owners in that household. The
522	     * ceiling is frozen on the owner at creation and later applied by
523	     * {@link OwnerMapper#toMembershipLevel(Owner)}. Returns {@code null} when the household has no
524	     * existing member (or the owner has no household id), meaning no cap applies.
525	     *
526	     * @param householdId the new owner's assigned household id
