773	        for (Owner existing : this.clinicService.findAllOwners()) {
774	            if (existing.isDeleted()) {
775	                continue;
776	            }
777	            if (excludeId != null && excludeId.equals(existing.getId())) {
778	                continue;
779	            }
780	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
781	                return true;
782	            }
783	        }
784	        return false;
