789	     * (soft) duplicate of: one whose identity key <em>differs</em> from the new owner's while sharing
790	     * the same last-name Soundex code (see {@link IdentityKeyUtils#soundex(String)}) and postcode. A
791	     * hard duplicate (identical identity key) has already been rejected with a 409 before this runs, so
792	     * this flags only the softer same-household-name overlap — in particular two owners with the same
793	     * last name and postcode but different telephones (whose identity keys therefore differ) are a soft
794	     * match rather than a rejected duplicate. The match with the lowest id is returned so the result is
795	     * deterministic when several owners qualify.
796	     *
797	     * @param owner the new owner being created, with its telephone already normalized
798	     * @return the matching existing owner, or {@code null} when none qualifies
799	     */
800	    private Owner findPossibleDuplicate(Owner owner) {
801	        if (owner.getLastName() == null || owner.getPostcode() == null) {
802	            return null;
803	        }
804	        String identityKey = ownerMapper.toIdentityKey(owner);
805	        String soundex = IdentityKeyUtils.soundex(owner.getLastName());
806	        return this.clinicService.findAllOwners().stream()
807	            .filter(existing -> !existing.isDeleted())
808	            .filter(existing -> !identityKey.equals(ownerMapper.toIdentityKey(existing)))
809	            .filter(existing -> soundex.equals(IdentityKeyUtils.soundex(existing.getLastName())))
810	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
811	            .min(Comparator.comparingInt(Owner::getId))
812	            .orElse(null);
813	    }
