291	    /**
292	     * Return the Pet with the given name, or null if none found for this Owner.
293	     *
294	     * @param name to test
295	     * @return true if pet name is already in use
296	     */
297	    public Pet getPet(String name) {
298	        return getPet(name, false);
299	    }
300	
301	    /**
302	     * Return the Pet with the given name, or null if none found for this Owner.
303	     *
304	     * @param name to test
305	     * @return true if pet name is already in use
306	     */
307	    public Pet getPet(String name, boolean ignoreNew) {
308	        name = name.toLowerCase();
309	        for (Pet pet : getPetsInternal()) {
310	            if (!ignoreNew || !pet.isNew()) {
311	                String compName = pet.getName();
312	                compName = compName.toLowerCase();
313	                if (compName.equals(name)) {
314	                    return pet;
315	                }
316	            }
317	        }
318	        return null;
319	    }
