241	     * immediately preceding the trailing HASH8 and CHK segments.
242	     */
243	    private static String memberIdFyDigits(String base) {
244	        int fyEnd = base.length() - HASH8_WIDTH - CHK_WIDTH;
245	        return base.substring(fyEnd - FY_WIDTH, fyEnd);
246	    }
