270	    /**
271	     * Derive an owner's version-2 duplicate-detection identity key: the lower-case SHA-256 hex digest
272	     * (64 characters) of the normalized E.164 telephone, the lower-cased email (empty when none), the
273	     * American Soundex code of the last name and the fixed {@link IdentityKeyUtils#IDENTITY_VERSION_TAG version tag},
274	     * joined with {@code '|'}. Mixing in the version tag means no key produced under version 1 is
275	     * produced again. Two owners are duplicates only when their whole identity keys are equal.
276	     *
277	     * <p>This is the single source of truth for the key: it is both returned on the DTO (under
278	     * {@code identity}) and used by the create endpoint's 409 duplicate check, so the value clients see
279	     * is exactly the value that governs rejection. The "email present" rule reuses
280	     * {@link #hasEmail(Owner)}, and the Soundex and hashing come from {@link IdentityKeyUtils}, the same
281	     * helpers the soft-match uses.
282	     */
283	    default String toIdentityKey(Owner owner) {
284	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
285	        String email = hasEmail(owner) ? owner.getEmail() : "";
286	        String soundex = IdentityKeyUtils.soundex(owner.getLastName());
287	        return IdentityKeyUtils.sha256Hex(
288	            telephone + "|" + email + "|" + soundex + "|" + IdentityKeyUtils.IDENTITY_VERSION_TAG);
289	    }
