307	    /**
308	     * Derive an owner's membership points: start at 0; add 2 when an email address is present; add 1
309	     * when the owner has no namesakes (namesakeCount is 0); add 2 when the owner belongs to a
310	     * household of 3 or more (see {@link #hasHouseholdBonus(Owner)}); add 3 when the owner's tenure
311	     * is at least one elapsed fiscal year (see {@link #hasTenureBonus(Owner)}). Because a newly
312	     * created owner has zero tenure it never earns the tenure points, so a new owner with an email
313	     * and no namesakes in a single-member household scores 3 points.
314	     */
315	    default Integer toMembershipPoints(Owner owner) {
316	        int points = 0;
317	        if (hasEmail(owner)) {
318	            points += 2;
319	        }
320	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
321	        if (noNamesakes) {
322	            points += 1;
323	        }
324	        if (hasHouseholdBonus(owner)) {
325	            points += 2;
326	        }
327	        if (hasTenureBonus(owner)) {
328	            points += 3;
329	        }
330	        return points;
