342	    /**
343	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
344	     * {@link #toMembershipPoints(Owner)}): level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6
345	     * or more.
346	     *
347	     * <p>The level is then capped at the owner's {@code membershipLevelCap} when one is present: a new
348	     * owner's membership level cannot exceed one above the current maximum membership level among their
349	     * existing household members, so the cap (frozen at creation, see the create endpoint) is the
350	     * ceiling applied here. When no cap is present (e.g. an owner created with no existing household
351	     * member, or a legacy record) the uncapped level stands.
352	     */
353	    default Integer toMembershipLevel(Owner owner) {
354	        int level = uncappedMembershipLevel(owner);
355	        Integer cap = owner.getMembershipLevelCap();
356	        if (cap != null && level > cap) {
357	            return cap;
358	        }
359	        return level;
360	    }
361	
362	    /**
363	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
364	     * {@link #toMembershipPoints(Owner)}) before any household ceiling is applied: level 1 for 0-1
365	     * points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
366	     */
367	    default Integer uncappedMembershipLevel(Owner owner) {
368	        int points = toMembershipPoints(owner);
369	        if (points <= 1) {
370	            return 1;
371	        }
372	        if (points <= 3) {
373	            return 2;
374	        }
375	        if (points <= 5) {
376	            return 3;
377	        }
378	        return 4;
379	    }
