435	        String tier = toMembershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
436	        String area = REGION_TIMEZONE.containsKey(toLocality(owner)) ? "METRO" : "REGIONAL";
437	        return tier + "_" + area;
