254	        }
255	        for (Owner existing : ownerRepository.findAll()) {
256	            if (existing.isDeleted()) {
257	                continue;
258	            }
259	            if (excludeId != null && excludeId.equals(existing.getId())) {
260	                continue;
261	            }
262	            if (householdId.equals(existing.getHouseholdId())) {
263	                return true;
264	            }
265	        }
