274	    /**
275	     * Normalizes a value for household comparison: leading/trailing whitespace is trimmed, internal
276	     * runs of whitespace are collapsed to a single space, and the result is lower-cased. This lets
277	     * two last names that differ only in case or whitespace be treated as the same household.
278	     *
279	     * @param value the raw value, possibly {@code null}
280	     * @return the normalized comparison key, or {@code ""} when the value is {@code null}
281	     */
282	    private static String normalizeForHousehold(String value) {
283	        if (value == null) {
284	            return "";
285	        }
286	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
287	    }
288	
289	    /**
290	     * Derives the stable version-2 household identifier shared by all owners with the same last name and
291	     * postcode. The value is deterministic (the first 12 upper-case hex characters of the SHA-256
292	     * digest of the normalized last name, the postcode and the fixed
293	     * {@link IdentityKeyUtils#IDENTITY_VERSION_TAG version tag}, joined with {@code '|'}), so every owner
294	     * in the same household is assigned an identical identifier regardless of creation order and
295	     * without any explicit linking. Mixing in the version tag means no household id produced under
296	     * version 1 is produced again.
297	     *
298	     * @param lastName the owner's last name
299	     * @param postcode the owner's postcode, possibly {@code null}
300	     * @return the stable household identifier
301	     */
302	    private static String householdIdFor(String lastName, String postcode) {
303	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode)
304	            + "|" + IdentityKeyUtils.IDENTITY_VERSION_TAG;
305	        return IdentityKeyUtils.sha256UpperHex(key).substring(0, 12);
306	    }
