3	import java.util.concurrent.ConcurrentHashMap;
4	import java.util.concurrent.ConcurrentMap;
5	
6	import org.springframework.stereotype.Component;
7	
8	/**
9	 * Remembers the owner created for each {@code Idempotency-Key} seen on the create-owner endpoint,
10	 * so that a create repeated with an already-seen key can return the originally created owner instead
11	 * of creating a duplicate.
12	 *
13	 * <p>The mapping is held in memory: a key that has never been recorded returns no id, and once a
14	 * successful create has associated a key with an owner id every later create carrying that same key
15	 * resolves to the same owner.
16	 */
17	@Component
18	public class IdempotencyKeyRegistry {
19	
20	    private final ConcurrentMap<String, Integer> ownerIdByKey = new ConcurrentHashMap<>();
21	
22	    /**
23	     * Returns the id of the owner previously created for the given key, or {@code null} when the key
24	     * has not been seen (or was blank/absent).
25	     *
26	     * @param key the raw {@code Idempotency-Key} header value, possibly {@code null}
27	     * @return the associated owner id, or {@code null} when none is recorded
28	     */
29	    public Integer findOwnerId(String key) {
30	        if (key == null || key.isBlank()) {
31	            return null;
32	        }
33	        return this.ownerIdByKey.get(key);
34	    }
35	
36	    /**
37	     * Records that the given key produced the owner with the given id. Blank or absent keys are
38	     * ignored. The first record for a key wins, so a repeated create never overwrites the original.
39	     *
40	     * @param key     the raw {@code Idempotency-Key} header value, possibly {@code null}
41	     * @param ownerId the id of the owner created for that key
42	     */
43	    public void record(String key, Integer ownerId) {
44	        if (key == null || key.isBlank() || ownerId == null) {
45	            return;
46	        }
47	        this.ownerIdByKey.putIfAbsent(key, ownerId);
48	    }
49	}
