18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.Locale;
23	
24	/**
25	 * Helpers backing the owner duplicate-detection identity key. The identity key is the lower-case
26	 * SHA-256 hex of the owner's normalized telephone, lower-cased email and the American Soundex code of
27	 * the last name, joined with {@code '|'} (see {@code OwnerMapper.toIdentityKey}). Both the key itself
28	 * and the soft-match (which compares the Soundex code and postcode) route through this single source of
29	 * truth, so the two cannot diverge.
30	 *
31	 * <p>These are deliberately plain {@code static} utilities in their own class rather than default
32	 * methods on the MapStruct owner mapper: a {@code String -> String} mapper method would be picked up by
33	 * MapStruct as an implicit type conversion and wrongly applied to unrelated String properties.
34	 */
35	public final class IdentityKeyUtils {
36	
37	    /**
38	     * The fixed version tag mixed into every derived owner identifier — the member id's region code, the
39	     * household id and the identity key — to produce the version-2 identity. Because the tag becomes part
40	     * of each identifier's pre-image (or, for the member id, its literal region segment), no value
41	     * produced under version 1 is produced again. This is the single source of truth shared by every
42	     * layer that derives an identifier; it is deliberately absent from the user-facing region derivations
43	     * (locality, timezone and the owner segment's derived region), which keep the plain region code.
44	     */
45	    public static final String IDENTITY_VERSION_TAG = "V2";
46	
47	    private IdentityKeyUtils() {
48	    }
49	
50	    /**
51	     * Computes the American Soundex code of a name: the (upper-cased) first letter followed by three
52	     * digits, zero-padded or truncated to exactly four characters. Consonants are coded 1-6 by group;
53	     * vowels and {@code H}/{@code W} are not coded. Adjacent letters with the same code, and same-code
54	     * letters separated only by {@code H} or {@code W}, collapse to a single digit, while same-code
55	     * letters separated by a vowel are coded separately. Non-letters are ignored.
56	     *
57	     * @param name the name to encode, possibly {@code null}
58	     * @return the four-character Soundex code, or {@code ""} when the name has no letters
59	     */
60	    public static String soundex(String name) {
61	        if (name == null) {
62	            return "";
63	        }
64	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
65	        if (letters.isEmpty()) {
66	            return "";
67	        }
68	        StringBuilder code = new StringBuilder();
69	        code.append(letters.charAt(0));
70	        char previousDigit = digit(letters.charAt(0));
71	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
72	            char c = letters.charAt(i);
73	            char d = digit(c);
74	            if (d != '0' && d != previousDigit) {
75	                code.append(d);
76	            }
77	            // A vowel resets the "previous digit" so a following same-code consonant is coded again;
78	            // H and W are transparent, keeping the previous digit so they cannot separate a repeat.
79	            if (c != 'H' && c != 'W') {
80	                previousDigit = d;
81	            }
82	        }
83	        while (code.length() < 4) {
84	            code.append('0');
85	        }
86	        return code.toString();
87	    }
88	
89	    private static char digit(char c) {
90	        return switch (c) {
91	            case 'B', 'F', 'P', 'V' -> '1';
92	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
93	            case 'D', 'T' -> '3';
94	            case 'L' -> '4';
95	            case 'M', 'N' -> '5';
96	            case 'R' -> '6';
97	            default -> '0'; // A, E, I, O, U, H, W, Y
98	        };
99	    }
100	
101	    /**
102	     * Computes the SHA-256 digest of the UTF-8 bytes of {@code value} and renders it as a lower-case
103	     * hex string (64 characters). This is the single digest-to-hex routine reused across the
104	     * application; the upper-case variant simply upper-cases this result.
105	     *
106	     * @param value the string to hash
107	     * @return the full SHA-256 digest as lower-case hex
108	     */
109	    public static String sha256Hex(String value) {
110	        try {
111	            byte[] digest = MessageDigest.getInstance("SHA-256")
112	                .digest(value.getBytes(StandardCharsets.UTF_8));
113	            StringBuilder sb = new StringBuilder(digest.length * 2);
114	            for (byte b : digest) {
115	                sb.append(String.format("%02x", b));
116	            }
117	            return sb.toString();
118	        } catch (NoSuchAlgorithmException ex) {
119	            throw new IllegalStateException("SHA-256 not available", ex);
120	        }
121	    }
122	
123	    /**
124	     * Computes the SHA-256 digest of the UTF-8 bytes of {@code value} and renders it as an upper-case
125	     * hex string (64 characters). Delegates to {@link #sha256Hex(String)} so the digest-to-hex logic
126	     * lives in one place.
127	     *
128	     * @param value the string to hash
129	     * @return the full SHA-256 digest as upper-case hex
130	     */
131	    public static String sha256UpperHex(String value) {
132	        return sha256Hex(value).toUpperCase(Locale.ROOT);
133	    }
134	
135	    /**
136	     * Computes a single Luhn check digit (0-9) over the decimal digits contained in {@code value}.
137	     * Non-digit characters (e.g. letters in a hex segment or separators) are ignored. This is the
138	     * single source of truth for the check digit used by the member id's {@code CHK} segment.
139	     *
140	     * @param value the string whose contained digits are checked
141	     * @return the Luhn check digit, 0 to 9
142	     */
143	    public static int luhnCheckDigit(String value) {
144	        int sum = 0;
145	        boolean dbl = true;
146	        for (int i = value.length() - 1; i >= 0; i--) {
147	            char c = value.charAt(i);
148	            if (c < '0' || c > '9') {
149	                continue;
150	            }
151	            int d = c - '0';
152	            if (dbl) {
153	                d *= 2;
154	                if (d > 9) {
155	                    d -= 9;
156	                }
157	            }
158	            sum += d;
159	            dbl = !dbl;
160	        }
161	        return (10 - (sum % 10)) % 10;
162	    }
163	}
